Step.Text:
PARAMS: JSON object {
  datumOd        (text, ISO date "YYYY-MM-DD", required)
  datumDo        (text, ISO date "YYYY-MM-DD", required)
  dobavljac      (text, exact supplier name — empty = all suppliers via LIKE %)
  fakturaPattern (text, LIKE pattern — empty = all invoices via %)
}

Value.Calculation:
Let ( [
~datumFull = Substitute ( $datumOd ; "T" ; Char(13) );
~datumDatum = GetValue ( ~datumFull ; 1 )
];

Date (
	GetAsNumber ( Middle ( ~datumDatum ; 6 ; 2 ) ) ;
	GetAsNumber ( Right  (~datumDatum ; 2 ) ) ;
	GetAsNumber ( Left   ( ~datumDatum ; 4 ) )
)

)

Let ( [
~datumFull = Substitute ( $datumDo ; "T" ; Char(13) );
~datumDatum = GetValue ( ~datumFull ; 1 )
];

Date (
	GetAsNumber ( Middle ( ~datumDatum ; 6 ; 2 ) ) ;
	GetAsNumber ( Right  (~datumDatum ; 2 ) ) ;
	GetAsNumber ( Left   ( ~datumDatum ; 4 ) )
)

)

JSONSetElement ( "{}" ;
	[ "datumPrimke"           ; epSQLResult ( $i ; 0  ; "rs_sp" )                        ; JSONString ] ;
	[ "brojFakturaDobavljaca" ; epSQLResult ( $i ; 1  ; "rs_sp" )                        ; JSONString ] ;
	[ "dobavljac"             ; epSQLResult ( $i ; 2  ; "rs_sp" )                        ; JSONString ] ;
	[ "dobavljacID"           ; epSQLResult ( $i ; 3  ; "rs_sp" )                        ; JSONString ] ;
	[ "sifra"                 ; epSQLResult ( $i ; 4  ; "rs_sp" )                        ; JSONString ] ;
	[ "naziv"                 ; epSQLResult ( $i ; 5  ; "rs_sp" )                        ; JSONString ] ;
	[ "jm"                    ; epSQLResult ( $i ; 6  ; "rs_sp" )                        ; JSONString ] ;
	[ "kolicina"              ; GetAsNumber ( epSQLResult ( $i ; 7  ; "rs_sp" ) )        ; JSONNumber ] ;
	[ "cijena"                ; GetAsNumber ( epSQLResult ( $i ; 8  ; "rs_sp" ) )        ; JSONNumber ] ;
	[ "ukupno"                ; GetAsNumber ( epSQLResult ( $i ; 9  ; "rs_sp" ) )        ; JSONNumber ] ;
	[ "brojFakture"           ; epSQLResult ( $i ; 10 ; "rs_sp" )                        ; JSONString ] ;
	[ "datumFakture"          ; epSQLResult ( $i ; 11 ; "rs_sp" )                        ; JSONString ] ;
	[ "spID"                  ; epSQLResult ( $i ; 12 ; "rs_sp" )                        ; JSONString ] ;
	[ "primkaID"              ; epSQLResult ( $i ; 13 ; "rs_sp" )                        ; JSONString ] ;
	[ "invoiceID"             ; epSQLResult ( $i ; 14 ; "rs_sp" )                        ; JSONString ] ;
	[ "fakturisana"           ; GetAsNumber ( epSQLResult ( $i ; 15 ; "rs_sp" ) )        ; JSONNumber ] ;
	[ "ufdID"                 ; epSQLResult ( $i ; 16 ; "rs_sp" )                        ; JSONString ]
)
